            ->pluck('key')
            ->map(fn($k) => trim($k))
            ->toArray();

        $filteredKeys = collect($keys)
            ->unique(fn($item) => trim($item['key']))
            ->filter(fn($item) => ! in_array(trim($item['key']), $existingKeys))
            ->map(fn($item) => [
                'key' => trim($item['key']),
                'created_at' => $now,
                'updated_at' => $now,
            ])
            ->values()
            ->toArray();

        if (count($filteredKeys) > 0) {
            // count($filteredKeys);
            \DB::table('translation_keys')->insert($filteredKeys);
        } else {
